_MAX_LIMIT = 200
_MAX_ATTEMPTS = 4


def _header(headers: dict[str, str], name: str) -> str | None:
    for k, v in headers.items():
        if k.lower() == name:
            return v
    return None


def _error_code(body: bytes) -> str:
    try:
        return str(json.loads(body)["error"]["code"])
    except Exception:
        return ""


def _retry_after(value: str | None, now: Callable[[], datetime]) -> float | None:
    """Seconds to wait per a Retry-After header value, or None when absent or unusable."""
    if value is None:
        return None
    value = value.strip()
    if value.isascii() and value.isdigit():
        return float(int(value))
    try:
        when = parsedate_to_datetime(value)
    except (TypeError, ValueError, IndexError):
        return None
    if when is None:
        return None
    if when.tzinfo is None:
        when = when.replace(tzinfo=timezone.utc)
    return max(0.0, (when - now()).total_seconds())


def _send(transport, path, params, sleep, now) -> Response:
    attempt = 0
    while True:
        attempt += 1
        r = transport(path, dict(params))
        if r.status == 200:
            return r
        if r.status in (429, 503) and attempt < _MAX_ATTEMPTS:
            wait = _retry_after(_header(r.headers, "retry-after"), now)
            if wait is None:
                wait = 1.0 if r.status == 429 else 2.0
            if wait > 0:
                sleep(wait)
            continue
        raise ApiError(r.status, _error_code(r.body))
